sysauto_script.script:
/**
 * Scheduled Script Execution: ConfigurationNOW - Collect current instance
 * Scope:   x_2160899_driftw_0
 * Run:     Daily, 02:15 (instance time zone)
 * Run as:  ConfigurationNOW collector service account (role x_2160899_driftw_0.collector)
 *
 * Collects the current instance's settings and writes them to the CMDB.
 */
(function () {
    var collector = new ConfigNowCollector();
    var snapshot = collector.collect();
    var result = new ConfigNowWriter().persist(snapshot);

    gs.info('[ConfigurationNOW] Collection complete for {0} in {1} ms. totals={2} warnings={3}',
        snapshot.instance.instance_name,
        snapshot.duration_ms,
        JSON.stringify(result.totals),
        snapshot.warnings.length);

    for (var i = 0; i < snapshot.warnings.length; i++) {
        gs.warn('[ConfigurationNOW] {0}: {1}', snapshot.warnings[i].area, snapshot.warnings[i].message);
    }
})();
